--
-- Name: products; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.products (
    id integer NOT NULL,
    name text NOT NULL,
    slug text NOT NULL,
    sku text NOT NULL,
    description text,
    short_description text,
    manufacturer_id integer,
    category_id integer,
    price numeric(10,2),
    cost numeric(10,2),
    weight numeric(10,2),
    dimensions text,
    show_price_online boolean DEFAULT true NOT NULL,
    available_online boolean DEFAULT true NOT NULL,
    in_store_only boolean DEFAULT false NOT NULL,
    featured boolean DEFAULT false NOT NULL,
    display_order integer DEFAULT 0 NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    low_stock_threshold integer DEFAULT 0 NOT NULL,
    specs jsonb,
    msrp numeric(10,2),
    markup_percent numeric(5,2),
    pricing_mode text DEFAULT 'fixed'::text NOT NULL,
    sale_price numeric(10,2),
    tags jsonb DEFAULT '[]'::jsonb,
    quote_only boolean DEFAULT false NOT NULL,
    frame_only_price numeric(10,2),
    featured_at timestamp with time zone,
    collection text,
    collection_slug text,
    seat_type text,
    umbrella_type text,
    umbrella_shape text,
    umbrella_size text,
    lift_mechanism text,
    tilt_mechanism text,
    pole_material text,
    sub_category text,
    sub_material text,
    finish_min_qty_note text,
    cushion_upgrade_sku text,
    catalog_visible boolean DEFAULT true NOT NULL,
    rank_group integer,
    CONSTRAINT products_lift_mechanism_check CHECK (((lift_mechanism IS NULL) OR (lift_mechanism = ANY (ARRAY['Crank'::text, 'Manual'::text, 'Pulley'::text, 'Quad Pulley'::text])))),
    CONSTRAINT products_pole_material_check CHECK (((pole_material IS NULL) OR (pole_material = ANY (ARRAY['Aluminum'::text, 'Fiberglass'::text, 'Wood'::text, 'Teak'::text, 'Steel'::text])))),
    CONSTRAINT products_pricing_mode_check CHECK ((pricing_mode = ANY (ARRAY['fixed'::text, 'cost_plus_markup'::text, 'msrp_minus_dealer_rate'::text]))),
    CONSTRAINT products_seat_type_check CHECK (((seat_type IS NULL) OR (seat_type = ANY (ARRAY['Sling'::text, 'Cushion'::text, 'Strap'::text, 'Wicker Weave'::text, 'Solid'::text, 'Padded Sling'::text])))),
    CONSTRAINT products_tilt_mechanism_check CHECK (((tilt_mechanism IS NULL) OR (tilt_mechanism = ANY (ARRAY['Auto'::text, 'Collar'::text, 'Push Button'::text, 'Glide'::text, 'Rotational'::text, 'None'::text])))),
    CONSTRAINT products_umbrella_shape_check CHECK (((umbrella_shape IS NULL) OR (umbrella_shape = ANY (ARRAY['Octagon'::text, 'Square'::text, 'Rectangle'::text, 'Round'::text])))),
    CONSTRAINT products_umbrella_type_check CHECK (((umbrella_type IS NULL) OR (umbrella_type = ANY (ARRAY['Cantilever'::text, 'Market'::text, 'Specialty'::text, 'Beach'::text]))))
);


